insert into public.companies(id,name,slug,description) values('00000000-0000-4000-8000-000000000001','VSP Innovations','vsp-innovations','We turn ambitious ideas into intelligent products. Bringing AI solutions, thoughtful engineering, and purposeful design together to build what comes next.') on conflict(id) do nothing;
insert into public.profiles(id,company_id,slug,first_name,last_name,display_name,title,headline,bio,active) values
('00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000001','arjun-devireddy','Arjun','Devireddy','Arjun Devireddy','Co-Founder','Building AI solutions & intelligent products.','Turning possibilities into products at VSP Innovations. Let’s connect around meaningful problems, intelligent technology, and the ideas that move us forward.',true),
('00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000001','kavya-kelam','Kavya','Kelam','Kavya Kelam','Co-Founder','Building AI solutions & intelligent products.','Turning possibilities into products at VSP Innovations. Let’s connect around meaningful problems, intelligent technology, and the ideas that move us forward.',true) on conflict(id) do nothing;
insert into public.expertise(profile_id,name,sort_order) select p.id, e.name,e.sort_order from public.profiles p cross join (values ('AI Solutions',0),('AI Products',1),('Intelligent Automation',2),('Product Development',3)) e(name,sort_order) where p.id in ('00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000012') and not exists(select 1 from public.expertise x where x.profile_id=p.id and x.name=e.name);
